/// Stardust — spend all current Stars; for each Star, hit a
/// uniform-random alive enemy. Mirrors Python's per-hit
/// `combat.rng.choice(combat.alive_enemies)` re-sampling shape at
/// `sts2-rl-agent@01c094d:sts2_env/cards/regent.py:L549-555` (one fresh
/// roll per iteration so chained-listener kills shrink the candidate
/// set on the next hit).
///
/// Bead `sts2-rs-c46l`: wires `card_effects::pick_random_alive_enemy`
/// in place of the prior first-alive fallback.
// Port-pin: sts2-rl-agent@01c094d:sts2_env/cards/regent.py:L540
pub(crate) fn play_stardust(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    // C# `Stardust.OnPlay` (Stardust.cs:24) hits `ResolveStarXValue()` times,
    // and that X value is `LastStarsSpent` (CardModel.cs:1139-1145), set by
    // `SpendStars` (CardModel.cs:1846-1854) during `SpendResources`
    // (CardModel.cs:1817-1830) — which runs BEFORE `OnPlay`. `SpendStars` always
    // `await Hook.AfterStarsSpent(...)`, so the spend must route through the
    // canonical `spend_stars` helper here: it is the ONLY site that fires the
    // `AfterStarsSpent` reactives (ChildOfTheStars block, BlackHole AoE,
    // GalacticDust/MiniRegent relics). A raw `state.player.stars = 0` spent the
    // stars silently and ran none of those (issue #177). Spend BEFORE dealing
    // the hits to match the C# SpendResources-before-OnPlay ordering.
    // Auto-play (Mayhem / Cascade / Catastrophe): the auto-play resolver stamped
    // `AutoPlayStarX = stars + 1` on this card. C# `CardCmd.AutoPlay` captures
    // `LastStarsSpent` WITHOUT `SpendResources`, so an auto-played Stardust hits
    // `Stars` times but does NOT spend the stars (regent-legal-action Fix B, seed
    // 2010). Manual play never sets the var, so it falls through to `spend_stars`
    // (SpendResources-before-OnPlay parity, routing AfterStarsSpent reactives).
    let auto_star_x = state
        .player
        .play
        .last()
        .and_then(|&uid| state.cards.get(uid.0.get() as usize - 1))
        .map_or(0, |c| c.combat_var(sts2_core::cards::VarKey::AutoPlayStarX));
    let hits = if auto_star_x > 0 {
        if let Some(idx) =
            sts2_core::card_effects::resolving_card_uid(state).map(|u| u.0.get() as usize - 1)
        {
            if let Some(card) = state.cards.get_mut(idx) {
                card.set_combat_var(sts2_core::cards::VarKey::AutoPlayStarX, 0);
            }
        }
        auto_star_x - 1
    } else {
        state.spend_stars(i32::from(state.player.stars))
    };
    if hits <= 0 {
        return EffectResult::Resolved;
    }
    let dmg = current_damage(state);
    for _ in 0..hits {
        let Some(uid) = card_effects::pick_random_alive_enemy(state) else {
            break;
        };
        let _ = deal_damage_player_to_enemy(state, uid, dmg);
    }
    EffectResult::Resolved
}

